    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const initialAngle = parseInt(document.getElementById('initial-angle').value);
    let angle = initialAngle;
    let velocity = 0;
    let isRunning = false;
    const gravity = 0.0981; // 9.81 m/s^2
    const pendulumLength = 200; // in pixels

    function update() {
      if (isRunning) {
        velocity += -gravity * Math.sin(angle) / pendulumLength;
        angle += velocity;
        if (angle > Math.PI / 2 || angle < -Math.PI / 2) {
          velocity *= -0.95; // reduce velocity to simulate loss of energy
