      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.save();
      ctx.translate(canvas.width / 2, canvas.height / 2);
      ctx.rotate(angle);
      ctx.beginPath();
      ctx.arc(0, 0, pendulumLength, 0, 2 * Math.PI);
      ctx.stroke();
      ctx.restore();
